font:400 1rem/1.6 "Inter",system-ui;
color:var(--ink);
border:1px solid var(--line);
border-radius:6px;
background:var(--soft);
padding:8px 10px;
margin:6px 0 12px;

border-radius:20px;
background:radial-gradient(ellipse at 50% 30%,rgba(var(--theme-rgb),.28) 0%,rgba(12,17,26,.85) 90%);
